            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">GOSSIP AS COOPERATION TECH</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The original reputation system</text>\n                    <circle cx=\"200\" cy=\"380\" r=\"80\" fill=\"rgba(59,130,246,0.3)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"385\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">ANNA</text>\n                    <circle cx=\"550\" cy=\"380\" r=\"80\" fill=\"rgba(236,72,153,0.3)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"385\" text-anchor=\"middle\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">TOM</text>\n                    <circle cx=\"900\" cy=\"380\" r=\"80\" fill=\"rgba(16,185,129,0.3)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"900\" y=\"385\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">SAM</text>\n                    <path d=\"M280 380 L470 380\" stroke=\"#10b981\" stroke-width=\"2\" stroke-dasharray=\"6\"/>\n                    <path d=\"M630 380 L820 380\" stroke=\"#10b981\" stroke-width=\"2\" stroke-dasharray=\"6\"/>\n                    <path d=\"M250 460 Q550 600 850 460\" stroke=\"#ffd700\" stroke-width=\"2\" stroke-dasharray=\"6\"/>\n                    <text x=\"550\" y=\"640\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">\"Did you hear what Tom did?\"</text>\n                    <rect x=\"100\" y=\"700\" width=\"900\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"755\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">WHAT GOSSIP DOES</text>\n                    <text x=\"550\" y=\"800\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Tracks cheaters, freeloaders, and helpers</text>\n                    <text x=\"550\" y=\"835\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Replaces direct observation with social memory</text>\n                </svg>",
