            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Why Australia is the strongest case</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"220\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">STABLE CLIMATE</text>\n                    <text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">No major climatic shift coincides</text>\n                    <text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">with the extinctions</text>\n                    <rect x=\"100\" y=\"460\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">ONE NEW VARIABLE</text>\n                    <text x=\"550\" y=\"570\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Sapiens arrival is the only</text>\n                    <text x=\"550\" y=\"610\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">significant change in the system</text>\n                </svg>",
