            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Why money unifies</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"220\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">UNIVERSAL ACCEPTANCE</text>\n                    <text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Works between people who agree</text>\n                    <text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">on nothing else at all</text>\n                    <rect x=\"100\" y=\"460\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">THE SOURCE OF VALUE</text>\n                    <text x=\"550\" y=\"570\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Belief, not metal.</text>\n                    <text x=\"550\" y=\"610\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Trust, not gold.</text>\n                </svg>",
