          "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The set-point and progress</text><rect x=\"100\" y=\"190\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">MOOD RETURNS TO BASELINE</text><text x=\"550\" y=\"300\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Highs fade, crashes recover</text><text x=\"550\" y=\"340\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">The thermostat resets</text><text x=\"550\" y=\"378\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Lottery winners and accident survivors alike</text><line x1=\"150\" y1=\"520\" x2=\"950\" y2=\"520\" stroke=\"#ffd700\" stroke-width=\"3\" stroke-dasharray=\"12\"/><path d=\"M150 520 L320 520 L390 400 L500 520 L620 520 L700 640 L820 520 L950 520\" stroke=\"#6366f1\" stroke-width=\"4\" fill=\"none\"/><circle cx=\"390\" cy=\"400\" r=\"9\" fill=\"#6366f1\"/><circle cx=\"700\" cy=\"640\" r=\"9\" fill=\"#ef4444\"/><text x=\"550\" y=\"705\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">The line always drifts home</text><rect x=\"150\" y=\"760\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(245,158,11,0.1)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"818\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">THE IMPLICATION</text><text x=\"550\" y=\"868\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Wealth and comfort cannot lift joy for long</text><text x=\"550\" y=\"908\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">A challenge to the whole progress story</text><text x=\"550\" y=\"945\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">We adapt, and reset</text></svg>",
